<?php
require_once __DIR__.'/../config/database.php';require_admin();$section=$_GET['section']??'lessons';$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$action=$_POST['action']??'';$kind=$_POST['kind']??'';if($action==='delete'){ $table=['lesson'=>'lessons','resource'=>'resources','activity'=>'activities','quiz'=>'quizzes'][$kind]??'';if($table){$st=$conn->prepare("DELETE FROM {$table} WHERE id=?");$st->execute([(int)$_POST['id']]);$message='Item deleted.';}}elseif($action==='add_lesson'){ $title=trim($_POST['title']??'');$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-', $title),'-'));$st=$conn->prepare('INSERT INTO lessons(title,slug,category,summary,body,minutes) VALUES(?,?,?,?,?,?)');$st->execute([$title,$slug,trim($_POST['category']??'Foundations'),trim($_POST['summary']??''),trim($_POST['body']??''),max(1,(int)($_POST['minutes']??8))]);$message='Lesson added.';}elseif($action==='add_resource'){ $st=$conn->prepare('INSERT INTO resources(title,kind,description,url) VALUES(?,?,?,?)');$st->execute([trim($_POST['title']??''),trim($_POST['kind']??'Guide'),trim($_POST['description']??''),trim($_POST['url']??'')]);$message='Resource added.';}elseif($action==='add_activity'){ $st=$conn->prepare('INSERT INTO activities(title,category,summary,steps) VALUES(?,?,?,?)');$st->execute([trim($_POST['title']??''),trim($_POST['category']??'Lab'),trim($_POST['summary']??''),trim($_POST['steps']??'')]);$message='Simulation activity added.';}}
$pageTitle='Manage platform';require __DIR__.'/../partials/header.php';$lists=['students'=>$conn->query("SELECT id,fullname title,email subtitle,role kind FROM users ORDER BY id DESC")->fetchAll(),'lessons'=>$conn->query("SELECT id,title,summary subtitle,category kind FROM lessons ORDER BY sort_order,id")->fetchAll(),'multimedia'=>$conn->query("SELECT id,title,description subtitle,kind FROM resources ORDER BY sort_order,id")->fetchAll(),'simulation'=>$conn->query("SELECT id,title,summary subtitle,category kind FROM activities ORDER BY sort_order,id")->fetchAll(),'quizzes'=>$conn->query("SELECT id,title,description subtitle,'Quiz' kind FROM quizzes ORDER BY id")->fetchAll()];$section=in_array($section,['students','lessons','multimedia','simulation','quizzes','results','reports'])?$section:'lessons'; ?>
<section class="content-wrap admin-manage"><a class="back-link" href="<?= e(app_url('admin/dashboard.php')) ?>">← Admin overview</a><span class="eyebrow">CONTENT & LEARNERS</span><h1><?= e(ucwords(str_replace('-',' ',$section))) ?></h1><nav class="admin-tabs"><?php foreach(['students'=>'Students','lessons'=>'Lessons','multimedia'=>'Multimedia','simulation'=>'Simulation','quizzes'=>'Quizzes','results'=>'Results','reports'=>'Reports'] as $key=>$label): ?><a class="<?= $section===$key?'selected':'' ?>" href="<?= e(app_url('admin/manage.php?section='.$key)) ?>"><?= e($label) ?></a><?php endforeach; ?></nav><?php if($message): ?><div class="notice success"><?= e($message) ?></div><?php endif; ?>
<?php if($section==='lessons'): ?><form method="post" class="admin-form"><h2>Add a lesson</h2><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="add_lesson"><div class="form-grid"><label>Title<input name="title" required></label><label>Category<input name="category" value="Foundations" required></label><label>Minutes<input name="minutes" type="number" min="1" value="8"></label><label class="wide">Summary<input name="summary" required></label><label class="wide">Lesson content<textarea name="body" rows="5" required></textarea></label></div><button class="button button-primary">Add lesson</button></form><?php elseif($section==='multimedia'): ?><form method="post" class="admin-form"><h2>Add a resource</h2><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="add_resource"><div class="form-grid"><label>Title<input name="title" required></label><label>Type<input name="kind" value="Guide"></label><label class="wide">Description<input name="description" required></label><label class="wide">URL<input name="url" type="url"></label></div><button class="button button-primary">Add resource</button></form><?php elseif($section==='simulation'): ?><form method="post" class="admin-form"><h2>Add a practice simulation</h2><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="add_activity"><div class="form-grid"><label>Title<input name="title" required></label><label>Category<input name="category" value="Network lab"></label><label class="wide">Summary<input name="summary" required></label><label class="wide">Steps<textarea name="steps" rows="4" required></textarea></label></div><button class="button button-primary">Add activity</button></form><?php endif; ?>
<?php if(in_array($section,['students','lessons','multimedia','simulation','quizzes'])): ?><div class="manage-list"><?php foreach($lists[$section] as $row): ?><div><span class="category-chip"><?= e($row['kind']) ?></span><strong><?= e($row['title']) ?></strong><small><?= e($row['subtitle']) ?></small><?php if($section!=='students'): ?><form method="post" onsubmit="return confirm('Delete this item?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="kind" value="<?= e(match($section){'lessons'=>'lesson','multimedia'=>'resource','simulation'=>'activity','quizzes'=>'quiz',default=>'lesson'}) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="button-danger">Delete</button></form><?php endif; ?></div><?php endforeach; ?></div><?php elseif(in_array($section,['results','reports'])): ?><div class="panel"><div class="table-wrap"><table><thead><tr><th>Student</th><th>Quiz</th><th>Score</th><th>Attempted</th></tr></thead><tbody><?php foreach($conn->query('SELECT u.fullname,q.title,a.score,a.total,a.attempted_at FROM quiz_attempts a JOIN users u ON u.id=a.user_id JOIN quizzes q ON q.id=a.quiz_id ORDER BY a.attempted_at DESC') as $a): ?><tr><td><?= e($a['fullname']) ?></td><td><?= e($a['title']) ?></td><td><?= (int)$a['score'] ?>/<?= (int)$a['total'] ?></td><td><?= e($a['attempted_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><button class="button button-primary" onclick="window.print()">Print / save report</button></div><?php endif; ?></section><?php require __DIR__.'/../partials/footer.php'; ?>
